<?php require 'config.php';require_login();$id=(int)($_GET['doctor']??$_POST['doctor_id']??0);$s=db()->prepare('SELECT * FROM doctors WHERE id=?');$s->execute([$id]);$d=$s->fetch(PDO::FETCH_ASSOC);if(!$d){flash('error','Doctor not found.');header('Location: doctors.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['date']??'';$time=$_POST['time']??'';$mode=$_POST['mode']??'';if(!$date||strtotime($date)<strtotime(date('Y-m-d'))||!in_array($time,['09:00','11:30','15:00','18:00'],true)||!in_array($mode,['Online','Clinic'],true)){flash('error','Select a valid future slot and consultation mode.');}else{$i=db()->prepare('INSERT INTO appointments(user_id,doctor_id,appointment_date,appointment_time,mode,notes) VALUES(?,?,?,?,?,?)');$i->execute([current_user()['id'],$id,$date,$time,$mode,trim($_POST['notes']??'')]);$n=db()->prepare('INSERT INTO notifications(user_id,message,channel) VALUES(?,?,?)');$n->execute([current_user()['id'],'Appointment confirmed with '.$d['name'],'Email/SMS demo']);flash('success','Appointment confirmed. A demo notification event was recorded.');header('Location: dashboard.php');exit;}}$title='Book Appointment | MediBook';require 'partials/header.php';?><section class="auth"><form method="post" class="panel wide"><span class="eyebrow">Appointment booking</span><h1><?=e($d['name'])?></h1><p><?=e($d['specialty'])?> • ₹<?=e($d['fee'])?></p><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="doctor_id" value="<?=e($id)?>"><div class="form-grid"><label>Date<input type="date" name="date" min="<?=date('Y-m-d')?>" required></label><label>Time<select name="time"><option>09:00</option><option>11:30</option><option>15:00</option><option>18:00</option></select></label><label>Mode<select name="mode"><option>Online</option><option>Clinic</option></select></label><label>Reason (demo only)<input name="notes" maxlength="160" placeholder="Do not enter sensitive medical data"></label></div><button class="btn">Confirm appointment</button></form></section><?php require 'partials/footer.php';?>